const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const POS={1:'GKP',2:'DEF',3:'MID',4:'FWD'},STATUS={a:'Available',d:'Doubtful',i:'Injured',s:'Suspended',u:'Unavailable',n:'Not available'};
let state={entryId:localStorage.getItem('fplEntryId')||'',bootstrap:null,entry:null,history:null,picks:null,live:null,fixtures:[],transfers:[],players:[],teams:new Map(),gw:1,season:null,advanced:new Map(),advancedLoading:false,publicLoaded:false,compare:new Set(),sort:{key:'score',dir:'desc'},topFilter:'score',leagueId:null,leagueAnalysis:null,leagueExposureFilter:'all',simHorizon:5,fixtureHorizon:5,fixtureSort:'easiest',freeTransfers:Number(localStorage.getItem('fplFreeTransfers')||1),externalImages:new Map(),transfers:[],transferSort:{key:'transfer_date',dir:'desc'},account:null,accountMode:'login'};
const hasNum=n=>n!==null&&n!==undefined&&n!==''&&Number.isFinite(Number(n)),fmt=n=>hasNum(n)?Number(n).toLocaleString():'—',dec=(n,d=2)=>hasNum(n)?Number(n).toFixed(d):'N/A',money=n=>hasNum(n)?`£${Number(n).toFixed(1)}m`:'N/A',clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),2600)};
async function api(url,opts){const r=await fetch(url,opts);let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.error||`Request failed (${r.status})`);return j}
function currentGw(){return state.bootstrap?.events?.find(e=>e.is_current)||state.bootstrap?.events?.find(e=>e.is_next)||state.bootstrap?.events?.[0]}
function teamObj(id){return state.teams.get(Number(id))||{name:'Unknown',short_name:'—',code:0}}
function teamName(id){return teamObj(id).short_name||teamObj(id).name}
function crest(id){const t=teamObj(id);return t.code?`https://resources.premierleague.com/premierleague/badges/70/t${t.code}.png`:''}
function photo(p){if(!p)return'';const ext=state.externalImages.get(p.id);if(ext)return ext;const raw=String(p.photo||'').replace(/\.jpg$/i,'');if(raw)return `https://resources.premierleague.com/premierleague/photos/players/110x140/p${raw}.png?v=${p.team||0}`;return p.code?`https://resources.premierleague.com/premierleague/photos/players/110x140/p${p.code}.png?v=${p.team||0}`:crest(p.team)}
function img(src,cls,alt){return src?`<img class="${cls}" src="${src}" alt="${esc(alt)}" loading="lazy" onerror="this.style.display='none'">`:''}
function pById(id){return state.players.find(p=>p.id===Number(id))}
function adv(p){return state.advanced.get(p.id)||null}
function livePts(id){return state.live?.elements?.find(x=>x.id===Number(id))?.stats?.total_points??null}
function inferSeason(){const d=new Date(),y=d.getUTCFullYear();return d.getUTCMonth()>=6?y:y-1}
function upcomingFixtures(p,n=5){return state.fixtures.filter(f=>!f.finished&&(f.team_h===p.team||f.team_a===p.team)).sort((a,b)=>(a.event||999)-(b.event||999)).slice(0,n)}
function fdrForFixture(f,teamId){return Number(f?.team_h===teamId?(f.team_h_difficulty||3):(f?.team_a===teamId?(f.team_a_difficulty||3):3))}
function fdrLabel(d){return({1:'Very Easy',2:'Easy',3:'Medium',4:'Hard',5:'Very Hard'})[Number(d)]||'Medium'}
function nextFixtureGameweeks(n=5){const ids=[...new Set(state.fixtures.filter(f=>!f.finished&&f.event!=null).map(f=>Number(f.event)))].sort((a,b)=>a-b);return ids.slice(0,n)}
function fixturesForTeamGw(teamId,gw){return state.fixtures.filter(f=>!f.finished&&Number(f.event)===Number(gw)&&(f.team_h===teamId||f.team_a===teamId))}
function teamFixtureEase(teamId,n=5){const gws=nextFixtureGameweeks(n),fx=gws.flatMap(g=>fixturesForTeamGw(teamId,g));if(!fx.length)return 50;const avg=fx.reduce((s,f)=>s+fdrForFixture(f,teamId),0)/fx.length;return clamp(100-(avg-1)*22,10,100)}
function fixtureMini(p,n=5,compact=false){const gws=nextFixtureGameweeks(n);return `<div class="fixture-run ${compact?'compact':''}">${gws.map(g=>{const fs=fixturesForTeamGw(p.team,g);if(!fs.length)return `<span class="fixture-mini blank" title="GW${g}: No fixture"><b>GW${g}</b><em>—</em></span>`;return fs.map(f=>{const home=f.team_h===p.team,opp=home?teamName(f.team_a):teamName(f.team_h),d=fdrForFixture(f,p.team);return `<span class="fixture-mini fdr-${d}" title="GW${g}: ${esc(opp)} (${home?'Home':'Away'}) · FDR ${d} ${fdrLabel(d)}"><b>${esc(opp)}</b><em>${home?'H':'A'} · ${d}</em></span>`}).join('')}).join('')}</div>`}
function fixtureScore(p,n=5){const fx=upcomingFixtures(p,n);if(!fx.length)return 50;const avg=fx.reduce((s,f)=>s+(f.team_h===p.team?(f.team_h_difficulty||3):(f.team_a_difficulty||3)),0)/fx.length;return clamp(100-(avg-1)*22,10,100)}
function minutesProb(p){const mins=+p.minutes||0;const starts=+p.starts||0;const app=Math.max(1,Math.round(mins/75));const base=mins?Math.min(1,mins/(app*90)):.35;const status=p.status==='a'?1:p.status==='d'?.7:.25;return clamp((starts?Math.min(1,starts/app):base)*.65+base*.35,0.15,1)*status}
function projectFixture(p,f){const ppg=+p.points_per_game||0,form=+p.form||0,xgi90=+p.expected_goal_involvements_per_90||0,cs90=+p.clean_sheets_per_90||0;let base=ppg*.45+form*.25+(p.element_type===1?cs90*1.2:xgi90*2.8)+1.0;const home=f.team_h===p.team,diff=home?(f.team_h_difficulty||3):(f.team_a_difficulty||3);const diffFactor={1:1.20,2:1.10,3:1,4:.88,5:.76}[diff]||1;const homeFactor=home?1.06:.96;return Math.max(0,base*diffFactor*homeFactor*minutesProb(p))}
function projectedTotal(p,n=5){return upcomingFixtures(p,n).reduce((s,f)=>s+projectFixture(p,f),0)}
function rawRating(p){const a=adv(p)||{},price=(+p.now_cost||0)/10,form=+p.form||0,xgi90=+p.expected_goal_involvements_per_90||0,ppg=+p.points_per_game||0,ict=+p.ict_index||0,value=+p.value_season||0,close=+a.close_chances||0,xps=+a.xg_per_shot||0,avail=p.status==='a'?1:p.status==='d'?.82:.52,fx=fixtureScore(p)/100,proj=projectedTotal(p,5);let role=p.element_type===1?(+p.saves||0)*.03+(+p.clean_sheets||0)*.55:p.element_type===2?(+p.clean_sheets||0)*.36+xgi90*4.2:xgi90*7.2;return (form*2.1+ppg*2+xgi90*8.2+ict*.03+value*.22+close*.28+xps*3+(price?6/price:0)+role+fx*3+proj*.12)*avail}
function score(p){return Math.round(clamp(rawRating(p)*2.55,0,100))}
function enriched(p){const a=adv(p)||{},price=(+p.now_cost||0)/10;return {...p,...a,teamName:teamName(p.team),position:POS[p.element_type],score:score(p),now_cost:price,fixture_score:fixtureScore(p),projected3:projectedTotal(p,3),projected4:projectedTotal(p,4),projected5:projectedTotal(p,5),dataCoverage:adv(p)?'Advanced':'FPL only'}}
function rec(p){const e=enriched(p);if(p.status!=='a')return{label:'Monitor',tone:'warn',why:STATUS[p.status]||'Availability concern'};if(e.score>=84&&+p.form>=5)return{label:'Strong Buy',tone:'strong',why:'Elite multi-metric profile'};if(e.score>=76)return{label:'Buy',tone:'good',why:'Strong current and forward profile'};if(e.score>=66)return{label:'Watch',tone:'neutral',why:'Useful profile; timing matters'};if(e.score<50)return{label:'Avoid',tone:'bad',why:'Weak current signal'};return{label:'Hold',tone:'neutral',why:'No strong transfer edge'}}
function setSync(t,live=false){$('#syncText').textContent=t;$('#dataHealth').textContent=t;$('.sync-pill').classList.toggle('live',live)}
function compareNum(v,op,t){if(!Number.isFinite(t))return true;v=Number(v);if(!Number.isFinite(v))return false;if(op==='>')return v>t;if(op==='>=')return v>=t;if(op==='<')return v<t;if(op==='<=')return v<=t;return Math.abs(v-t)<.051}
function optionalNumber(id){const el=$(id),raw=el?.value?.trim?.()??'';if(raw==='')return NaN;const n=Number(raw);return Number.isFinite(n)?n:NaN}
function missingSortValue(v){if(v===null||v===undefined||v==='')return true;if(typeof v==='string'&&/^n\/?a$/i.test(v.trim()))return true;const n=Number(v);if(typeof v!=='string'&&Number.isFinite(n)===false)return true;return false}
function sortRows(rows,key,dir){const m=dir==='asc'?1:-1;rows.sort((a,b)=>{let x=a[key],y=b[key];const mx=missingSortValue(x),my=missingSortValue(y);if(mx&&my)return 0;if(mx)return 1;if(my)return -1;const nx=Number(x),ny=Number(y);if(Number.isFinite(nx)&&Number.isFinite(ny))return (nx-ny)*m;return String(x??'').localeCompare(String(y??''),undefined,{numeric:true,sensitivity:'base'})*m});return rows}
function setConnectState(connected=false){const b=$('#connectBtn');if(!b)return;b.innerHTML=connected?'FPL Connected <b>✓</b>':'Connect FPL <b>→</b>';b.classList.toggle('connected',connected)}
function estimateFT(){if(!state.history?.current?.length)return 1;let carried=1;for(const h of state.history.current){if(h.event<=1)continue;const chip=(state.history.chips||[]).find(c=>c.event===h.event)?.name;const paid=Math.round((+h.event_transfers_cost||0)/4);const freeUsed=(chip==='wildcard'||chip==='freehit')?0:Math.max(0,(+h.event_transfers||0)-paid);carried=Math.max(0,carried-freeUsed);carried=Math.min(5,carried+1)}return clamp(carried,1,5)}
function loadProfilePhoto(){const d=localStorage.getItem('hishoProfilePhoto');if(d){$('#profilePhoto').src=d;$('#profilePhoto').style.display='block';$('#profileInitials').style.display='none'}}

async function loadPublicData(force=false){
  if(state.publicLoaded&&state.players.length&&!force)return true;
  setSync('Loading official FPL data…');
  try{
    const [b,fx]=await Promise.all([api('/api/fpl/bootstrap'),api('/api/fpl/fixtures')]);
    state.bootstrap=b;state.fixtures=fx||[];state.players=b.elements||[];state.teams=new Map((b.teams||[]).map(t=>[t.id,t]));state.gw=currentGw()?.id||1;state.season=inferSeason();state.publicLoaded=true;
    populateTeamFilter();
    $('#gwLabel').textContent=`GAMEWEEK ${state.gw}`;
    $('#mAdvanced').textContent=`${state.advanced.size}/${state.players.length}`;
    renderTop();renderPlayers();renderCompare();renderFixtures();renderNewsQuick();
    setSync(`FPL data · GW${state.gw}`,true);
    loadAdvanced();
    return true;
  }catch(e){setSync('FPL data unavailable');toast(e.message);return false}
}
async function connect(id=state.entryId){
  if(!id)return $('#connectDialog').showModal();
  state.entryId=String(id).trim();localStorage.setItem('fplEntryId',state.entryId);setSync('Syncing your FPL team…');
  await loadPublicData();
  try{
    const [e,h,tr]=await Promise.all([api(`/api/fpl/entry/${state.entryId}`),api(`/api/fpl/entry/${state.entryId}/history`),api(`/api/fpl/entry/${state.entryId}/transfers`).catch(()=>[])]);
    state.entry=e;state.history=h;state.transfers=tr||[];
    const [pk,lv]=await Promise.allSettled([api(`/api/fpl/entry/${state.entryId}/picks/${state.gw}`),api(`/api/fpl/live/${state.gw}`)]);
    state.picks=pk.status==='fulfilled'?pk.value:null;state.live=lv.status==='fulfilled'?lv.value:null;state.freeTransfers=estimateFT();localStorage.setItem('fplFreeTransfers',state.freeTransfers);$('#freeTransfers').value=state.freeTransfers;
    renderAll();setSync(`Live · GW${state.gw}`,true);setConnectState(true);loadAdvanced();toast('FPL connected');
  }catch(e){setSync(`FPL data · GW${state.gw}`,true);setConnectState(false);toast(`Team connection: ${e.message}`);renderPlayers();renderFixtures()}
}
async function loadAdvanced(){if(!state.players.length||state.advancedLoading)return;state.advancedLoading=true;$('#understatHealth').textContent='Advanced: matching shots…';$('#understatStatusText').textContent='Loading shot-level enrichment from the current Understat AJAX feed…';$('#understatDot').className='loading';try{const d=await api(`/api/understat/player-shots/${state.season}`);state.advanced=new Map((d.players||[]).map(x=>[Number(x.fpl_id),x]));$('#understatHealth').textContent=`Advanced: ${d.matched}/${state.players.length}`;$('#understatStatusText').textContent=d.matched?`${d.matched} players matched · ${d.shots} shots · ${d.matches} completed matches`:'No completed-shot data matched yet; official FPL metrics are still available.';$('#understatDot').className=d.matched?'ok':'bad'}catch(e){$('#understatHealth').textContent='Advanced: temporarily unavailable';$('#understatStatusText').textContent='Official FPL data remains available. Shot-only metrics display N/A instead of false zeros.';$('#understatDot').className='bad'}finally{state.advancedLoading=false;$('#mAdvanced').textContent=`${state.advanced.size}/${state.players.length}`;renderTop();renderPlayers();renderCompare();if(state.entry)renderAll()}}
function renderAll(){renderTop();renderPlayers();renderCompare();renderFixtures();renderNewsQuick();renderTransfers();renderAccount();if(!state.entry)return;const e=state.entry;$('#gwLabel').textContent=`GAMEWEEK ${state.gw}`;$('#heroSub').textContent=`${e.name} · ${e.player_first_name||''} ${e.player_last_name||''} · updated ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;$('#heroPoints').textContent=fmt(e.summary_event_points);$('#heroRank').textContent=e.summary_overall_rank?`#${fmt(e.summary_overall_rank)}`:'—';$('#heroValue').textContent=money((e.last_deadline_value||0)/10);$('#heroFT').textContent=state.freeTransfers;$('#mPoints').textContent=fmt(e.summary_event_points);$('#mBank').textContent=money((e.last_deadline_bank||0)/10);$('#mTransfers').textContent=state.freeTransfers;$('#mTransfersSub').textContent='Estimated from public history · editable';$('#mAdvanced').textContent=`${state.advanced.size}/${state.players.length}`;renderDashboardActions();renderPlanner();renderSquad();renderLeagues();renderSimulator();loadHistory()}
function topMetric(p,k){const e=enriched(p);if(k==='captain')return e.score*.8+(+p.expected_goal_involvements_per_90||0)*18+e.projected3*1.2;if(k==='differential')return e.score-(+p.selected_by_percent||0)*.55+e.projected3;if(k==='value')return e.score*.35+(+p.total_points||0)/(e.now_cost||1)*2+e.projected5*.4;if(k==='xgi')return (+p.expected_goal_involvements_per_90||0)*100+e.score*.25;if(k==='close'){const a=adv(p);return a?(+a.close_chances||0)*8+(+a.xg_per_shot||0)*25+e.score*.1:-999}return e.score+e.projected5*.2}
function renderTop(){if(!state.players.length)return;let arr=state.players.filter(p=>p.minutes>0||state.gw<=2);if(state.topFilter==='differential')arr=arr.filter(p=>+p.selected_by_percent<12);arr=arr.sort((a,b)=>topMetric(b,state.topFilter)-topMetric(a,state.topFilter)).slice(0,8);$('#topPlayers').className='recommend-grid';$('#topPlayers').innerHTML=arr.map((p,i)=>{const e=enriched(p),a=adv(p),r=rec(p);return `<article class="recommend-card" data-player="${p.id}"><span class="rank-badge">${i+1}</span><div class="player-visual">${img(photo(p),'player-photo',p.web_name)}${img(crest(p.team),'club-crest',teamName(p.team))}<div class="rating-ring" style="--rating:${e.score}"><b>${e.score}</b><span>RATING</span></div></div><div class="recommend-body"><div class="recommend-title"><div><h4>${esc(p.web_name)}</h4><span>${teamName(p.team)} · ${POS[p.element_type]} · ${money(e.now_cost)}</span></div><span class="rec ${r.tone}">${r.label}</span></div><div class="mini-stats"><div><b>${dec(p.form,1)}</b><span>Form</span></div><div><b>${dec(p.expected_goal_involvements_per_90,2)}</b><span>xGI/90</span></div><div><b>${a?fmt(a.close_chances):'N/A'}</b><span>Big chances*</span></div><div><b>${a?.avg_shot_distance_m?`${dec(a.avg_shot_distance_m,1)}m`:'N/A'}</b><span>Avg shot</span></div><div><b>${dec(e.projected5,1)}</b><span>Proj 5 GWs</span></div><div><b>${dec(p.selected_by_percent,1)}%</b><span>Global own</span></div></div><div class="card-fixtures"><span>Next fixtures</span>${fixtureMini(p,5,true)}</div><span class="data-pill ${a?'full':'partial'}">${a?'● Advanced shot data':'◐ FPL data only'}</span><div class="card-actions"><button class="ghost" data-details="${p.id}">Details</button><button class="secondary" data-compare="${p.id}">${state.compare.has(p.id)?'Added ✓':'Compare +'}</button></div></div></article>`}).join('');bindPlayerButtons()}
function ownIds(){return new Set((state.picks?.picks||[]).map(x=>x.element))}
function plannerData(){const own=[...(state.picks?.picks||[])].map(x=>pById(x.element)).filter(Boolean).map(enriched);const bank=(state.entry?.last_deadline_bank||0)/10,h=Number($('#plannerHorizon')?.value||5),projKey=`projected${h}`;const sell=[...own].sort((a,b)=>((a[projKey]||0)+a.score*.11)-((b[projKey]||0)+b.score*.11)).slice(0,Math.max(2,state.freeTransfers));const buy=[];for(const s of sell){const budget=s.now_cost+bank;const cand=state.players.filter(p=>!ownIds().has(p.id)&&p.element_type===s.element_type&&p.status==='a').map(enriched).filter(p=>p.now_cost<=budget+.001).sort((a,b)=>(b[projKey]+b.score*.12)-(a[projKey]+a.score*.12))[0];if(cand)buy.push({for:s,...cand})}const sellIds=new Set(sell.slice(0,state.freeTransfers).map(x=>x.id));const keep=own.filter(x=>!sellIds.has(x.id)).sort((a,b)=>b[projKey]-a[projKey]);const monitor=state.players.filter(p=>!ownIds().has(p.id)&&p.status==='a').map(enriched).filter(p=>!buy.some(b=>b.id===p.id)).sort((a,b)=>(b[projKey]+b.score*.12)-(a[projKey]+a.score*.12)).slice(0,8);return{sell:sell.slice(0,state.freeTransfers),buy:buy.slice(0,state.freeTransfers),keep,monitor,bank,h,projKey}}
function decisionCard(p,labelExtra=''){return `<button class="decision-card" data-details="${p.id}">${img(photo(p),'',p.web_name)}<div><strong>${esc(p.web_name)}</strong><small>${teamName(p.team)} · ${POS[p.element_type]} · ${money(p.now_cost)}</small><span>Rating ${p.score} · ${dec(p[`projected${Number($('#plannerHorizon')?.value||5)}`],1)} projected</span>${labelExtra}${fixtureMini(p,3,true)}</div><em>${p.score}</em></button>`}
function renderPlanner(){if(!state.picks)return;const d=plannerData();$('#plannerSummary').innerHTML=`<div><span>Free transfers</span><b>${state.freeTransfers}</b></div><div><span>Bank</span><b>${money(d.bank)}</b></div><div><span>Planning horizon</span><b>${d.h} GWs</b></div><div><span>Suggested moves</span><b>${d.buy.length}</b></div>`;$('#sellList').innerHTML=d.sell.map(p=>decisionCard(p,'<span>Lowest forward value in your squad</span>')).join('')||'<div class="empty">No priority sells.</div>';$('#buyList').innerHTML=d.buy.map(p=>decisionCard(p,`<span>Suggested replacement for ${esc(p.for.web_name)}</span>`)).join('')||'<div class="empty">No affordable upgrade found.</div>';$('#keepList').innerHTML=d.keep.slice(0,10).map(p=>decisionCard(p,'<span>Keep: competitive forward profile</span>')).join('');$('#monitorList').innerHTML=d.monitor.map(p=>decisionCard(p,'<span>Watch for fixtures, role or price movement</span>')).join('');$('#sellCount').textContent=d.sell.length;$('#buyCount').textContent=d.buy.length;$('#keepCount').textContent=d.keep.length;$('#monitorCount').textContent=d.monitor.length;$$('.decision-card').forEach(x=>x.onclick=()=>openPlayer(+x.dataset.details))}
function renderDashboardActions(){if(!state.picks)return;const d=plannerData();$('#dashboardActions').className='action-summary';$('#dashboardActions').innerHTML=`<div><span>Sell priority</span><b>${esc(d.sell[0]?.web_name||'None')}</b></div><div><span>Buy priority</span><b>${esc(d.buy[0]?.web_name||'None')}</b></div><div><span>Best keep</span><b>${esc(d.keep[0]?.web_name||'—')}</b></div><div><span>Monitor</span><b>${esc(d.monitor[0]?.web_name||'—')}</b></div>`}
function leagueLabelForPlayer(id){if(!state.leagueAnalysis)return null;const x=state.leagueAnalysis.exposure?.find(e=>e.playerId===id);if(!x)return null;const own=ownIds().has(id);if(own&&x.selectionPct<=20)return{txt:`DIFF ${dec(x.selectionPct,0)}%`,cls:'diff'};if(!own&&x.selectionPct>=45)return{txt:`RISK ${dec(x.selectionPct,0)}%`,cls:'risk'};return null}
function renderSquad(){if(!state.picks){$('#fullSquad').innerHTML='<div class="empty">Connect your FPL Entry ID.</div>';return}const picks=state.picks.picks||[];const groups={1:[],2:[],3:[],4:[],bench:[]};picks.forEach(pk=>{const p=pById(pk.element);if(!p)return;(pk.position<=11?groups[p.element_type]:groups.bench).push({pk,p})});const row=(title,arr)=>`<div class="pitch-row" aria-label="${title}">${arr.map(({pk,p})=>{const e=enriched(p),lab=leagueLabelForPlayer(p.id);return `<div class="pitch-player" data-details="${p.id}"><div class="pitch-art">${lab?`<span class="league-flag ${lab.cls}">${lab.txt}</span>`:''}${img(photo(p),'player',p.web_name)}${img(crest(p.team),'crest',teamName(p.team))}</div><div class="nameplate">${esc(p.web_name)}${pk.is_captain?' ©':''}<span>${livePts(p.id)??'—'} pts · ${money(e.now_cost)}</span></div><div class="pitch-proj">Next 5: <b>${dec(e.projected5,1)}</b> pts</div>${fixtureMini(p,1,true)}</div>`}).join('')}</div>`;$('#fullSquad').innerHTML=row('Goalkeepers',groups[1])+row('Defenders',groups[2])+row('Midfielders',groups[3])+row('Forwards',groups[4])+`<div class="pitch-row">${groups.bench.length?groups.bench.map(({pk,p})=>`<div class="pitch-player" data-details="${p.id}"><div class="pitch-art">${img(photo(p),'player',p.web_name)}${img(crest(p.team),'crest',teamName(p.team))}</div><div class="nameplate">${esc(p.web_name)}<span>Bench · ${livePts(p.id)??'—'} pts</span></div></div>`).join(''):''}</div>`;$$('#fullSquad [data-details]').forEach(x=>x.onclick=()=>openPlayer(+x.dataset.details))}
function populateTeamFilter(){const s=$('#fTeam');s.innerHTML='<option value="">All clubs</option>'+[...state.teams.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}
function filteredRows(){let rows=state.players.map(enriched);const q=(($('#playerSearch').value)||'').toLowerCase(),fp=(($('#fPlayer').value)||'').toLowerCase(),team=$('#fTeam').value,pos=$('#fPos').value,status=$('#fStatus').value,data=$('#fData').value,r=optionalNumber('#fRating'),pr=optionalNumber('#fPrice'),own=optionalNumber('#fOwned'),xgi=optionalNumber('#fXgi90'),mins=optionalNumber('#fMinutes'),dist=optionalNumber('#fDist'),distOp=$('#fDistOp')?.value||'<=';rows=rows.filter(p=>(!q||`${p.web_name} ${p.teamName}`.toLowerCase().includes(q))&&(!fp||p.web_name.toLowerCase().includes(fp))&&(!team||String(p.team)===team)&&(!pos||p.position===pos)&&(!status||p.status===status)&&(!data||(data==='advanced'?p.dataCoverage==='Advanced':p.dataCoverage==='FPL only'))&&compareNum(p.score,$('#fRatingOp').value,r)&&compareNum(p.now_cost,$('#fPriceOp').value,pr)&&(!Number.isFinite(own)||+p.selected_by_percent>=own)&&(!Number.isFinite(xgi)||+p.expected_goal_involvements_per_90>=xgi)&&(!Number.isFinite(mins)||+p.minutes>=mins)&&compareNum(p.avg_shot_distance_m,distOp,dist));return sortRows(rows,state.sort.key,state.sort.dir)}
function v(v,d=2,s=''){return hasNum(v)?`${Number(v).toFixed(d)}${s}`:'<span class="na">N/A</span>'}
function renderPlayers(){if(!state.players.length){$('#rowCount').textContent='Loading players…';$('#playerTable tbody').innerHTML='<tr class="empty-row"><td colspan="25">Official FPL player data is loading…</td></tr>';return}const rows=filteredRows();$('#rowCount').textContent=`${rows.length} of ${state.players.length} players`;if(!rows.length){$('#playerTable tbody').innerHTML='<tr class="empty-row"><td colspan="25"><b>No players match these filters.</b><span>Clear the filters or change the comparison values.</span></td></tr>';updateSortHeaders();return}$('#playerTable tbody').innerHTML=rows.map(p=>`<tr data-details="${p.id}"><td><button class="compare-add ${state.compare.has(p.id)?'active':''}" data-compare="${p.id}">${state.compare.has(p.id)?'✓':'+'}</button></td><td><div class="player-cell">${img(photo(p),'table-photo',p.web_name)}<div><b>${esc(p.web_name)}</b><span>${STATUS[p.status]||p.status}</span></div></div></td><td>${p.teamName}</td><td>${p.position}</td><td>${money(p.now_cost)}</td><td><span class="score-chip">${p.score}</span></td><td>${v(p.selected_by_percent,1,'%')}</td><td>${v(p.form,1)}</td><td>${fmt(p.total_points)}</td><td>${v(p.points_per_game,1)}</td><td>${v(p.expected_goal_involvements_per_90,2)}</td><td>${v(p.expected_goals_per_90,2)}</td><td>${v(p.expected_assists_per_90,2)}</td><td>${fmt(p.goals_scored)}</td><td>${fmt(p.assists)}</td><td>${adv(p)?fmt(p.shots):'<span class="na">N/A</span>'}</td><td>${adv(p)?fmt(p.shots_on_target):'<span class="na">N/A</span>'}</td><td>${adv(p)?v(p.xg_per_shot,3):'<span class="na">N/A</span>'}</td><td>${adv(p)&&p.avg_shot_distance_m?v(p.avg_shot_distance_m,1,'m'):'<span class="na">N/A</span>'}</td><td>${adv(p)?fmt(p.close_chances):'<span class="na">N/A</span>'}</td><td>${adv(p)?fmt(p.very_close_shots):'<span class="na">N/A</span>'}</td><td>${adv(p)?fmt(p.big_xg_missed):'<span class="na">N/A</span>'}</td><td><div class="table-fixtures"><b>${Math.round(p.fixture_score)}</b>${fixtureMini(p,3,true)}</div></td><td>${v(p.projected5,1)}</td><td><span class="data-pill ${adv(p)?'full':'partial'}">${adv(p)?'Advanced':'FPL only'}</span></td></tr>`).join('');$$('#playerTable [data-compare]').forEach(x=>x.onclick=e=>{e.stopPropagation();toggleCompare(+x.dataset.compare)});$$('#playerTable tbody tr').forEach(x=>x.ondblclick=()=>openPlayer(+x.dataset.details));updateSortHeaders()}
function updateSortHeaders(){$$('#playerTable th[data-key]').forEach(th=>{const active=th.dataset.key===state.sort.key;th.textContent=th.textContent.replace(/[↑↓]$/,'').trim()+(active?(state.sort.dir==='asc'?' ↑':' ↓'):'')})}
function toggleCompare(id){id=Number(id);state.compare.has(id)?state.compare.delete(id):(state.compare.size<4?state.compare.add(id):toast('Compare up to 4 players'));updateCompare();renderPlayers();renderTop();renderCompare()}
function updateCompare(){const ids=[...state.compare];$('#compareCount').textContent=ids.length;$('#compareTrayCount').textContent=ids.length;$('#compareTray').classList.toggle('show',ids.length>0);$('#compareTrayPlayers').innerHTML=ids.map(id=>`<button data-remove="${id}">${esc(pById(id)?.web_name||'')} ×</button>`).join('');$$('[data-remove]').forEach(x=>x.onclick=()=>toggleCompare(+x.dataset.remove))}
function bestAlternatives(p){const e=enriched(p);return state.players.filter(x=>x.id!==p.id&&x.element_type===p.element_type&&x.status==='a').map(enriched).filter(x=>x.now_cost<=e.now_cost+2).sort((a,b)=>(b.score+b.projected5)-(a.score+a.projected5)).slice(0,3)}
function renderCompare(){const sel=[...state.compare].map(pById).filter(Boolean).map(enriched);if(!sel.length){$('#comparisonBoard').className='comparison-board empty';$('#comparisonBoard').innerHTML='Add players from Player Lab or recommendations.';$('#alternativeBoard').className='alternative-grid empty';$('#alternativeBoard').innerHTML='Select players to see alternatives.';return}const metrics=[['score','Hub rating',100,false],['form','Form',10,false],['expected_goal_involvements_per_90','xGI/90',1.2,false],['projected5','Projected 5 GWs',35,false],['points_per_game','Points/game',10,false],['selected_by_percent','Ownership %',70,false],['xg_per_shot','xG/shot',.5,false],['avg_shot_distance_m','Avg shot distance',30,true],['fixture_score','Fixture score',100,false]];$('#comparisonBoard').className='comparison-board';$('#comparisonBoard').innerHTML=`<div class="compare-head"><div></div>${sel.map(p=>`<div class="compare-player">${img(photo(p),'',p.web_name)}<b>${esc(p.web_name)}</b><span>${p.teamName} · ${p.position} · ${money(p.now_cost)}</span><em>${rec(p).label}</em><button data-remove="${p.id}">×</button></div>`).join('')}</div>${metrics.map(([k,l,max,lower])=>{const vals=sel.map(p=>Number(p[k])).filter(Number.isFinite),best=vals.length?(lower?Math.min(...vals):Math.max(...vals)):null;return `<div class="compare-row"><div class="metric-label">${l}</div>${sel.map(p=>{const n=Number(p[k]),ok=Number.isFinite(n),isBest=ok&&n===best,pct=ok?(lower?clamp((max-n)/max*100,0,100):clamp(n/max*100,0,100)):0;return `<div class="compare-value ${isBest?'best':''}"><div><b>${ok?dec(n,k==='score'?0:k==='avg_shot_distance_m'?1:2):'N/A'}</b>${isBest?'<span>BEST</span>':''}</div><i><u style="width:${pct}%"></u></i></div>`}).join('')}</div>`}).join('')}`;$$('#comparisonBoard [data-remove]').forEach(x=>x.onclick=()=>toggleCompare(+x.dataset.remove));$('#alternativeBoard').className='alternative-grid';$('#alternativeBoard').innerHTML=sel.map(p=>`<article class="alternative-card"><div class="alt-current">${img(photo(p),'',p.web_name)}<div><span>Selected</span><b>${esc(p.web_name)}</b><small>${money(p.now_cost)} · rating ${p.score} · proj ${dec(p.projected5,1)}</small></div></div><div class="versus">VS RECOMMENDED</div><div class="alt-options">${bestAlternatives(p).map((a,i)=>`<button data-details="${a.id}">${img(crest(a.team),'',a.teamName)}<div><span>${i?'Alternative':'Recommended'}</span><b>${esc(a.web_name)}</b><small>${money(a.now_cost)} · rating ${a.score} · proj ${dec(a.projected5,1)}</small></div><em>${a.score-p.score>=0?'+':''}${a.score-p.score}</em></button>`).join('')}</div></article>`).join('');$$('#alternativeBoard [data-details]').forEach(x=>x.onclick=()=>openPlayer(+x.dataset.details))}
function openPlayer(id){const p=pById(id);if(!p)return;const e=enriched(p),a=adv(p),r=rec(p),fx=upcomingFixtures(p,5);const fields=Object.entries(e).filter(([k,v])=>v!==null&&v!==''&&typeof v!=='object'&&!['news','photo'].includes(k)).sort(([a],[b])=>a.localeCompare(b));$('#playerDialogContent').innerHTML=`<div class="player-hero"><div class="player-hero-art">${img(photo(p),'modal-photo',p.web_name)}${img(crest(p.team),'modal-crest',teamName(p.team))}</div><div><span class="eyebrow">PLAYER INTELLIGENCE</span><h2>${esc(`${p.first_name||''} ${p.second_name||p.web_name}`)}</h2><p>${teamObj(p.team).name} · ${POS[p.element_type]} · ${money(e.now_cost)} · ${STATUS[p.status]||p.status}</p><div class="player-tags"><span class="rec ${r.tone}">${r.label}</span><span>Rating ${e.score}</span><span>${dec(p.selected_by_percent,1)}% global ownership</span><span>${a?'Advanced shots matched':'FPL data only'}</span></div></div><button class="icon-btn" id="closePlayer">×</button></div><div class="player-summary"><div class="big-rating"><span>HUB RATING</span><b>${e.score}</b><span>${r.why}</span></div><div class="detail-kpis"><div><span>xGI/90</span><b>${dec(p.expected_goal_involvements_per_90,2)}</b></div><div><span>Proj 5 GWs</span><b>${dec(e.projected5,1)}</b></div><div><span>Avg shot</span><b>${a?.avg_shot_distance_m?`${dec(a.avg_shot_distance_m,1)}m`:'N/A'}</b></div><div><span>Big chances*</span><b>${a?fmt(a.close_chances):'N/A'}</b></div><div><span>≤8m shots</span><b>${a?fmt(a.very_close_shots):'N/A'}</b></div><div><span>xG/shot</span><b>${a?dec(a.xg_per_shot,3):'N/A'}</b></div></div></div><div class="quick-chips">${fx.map(f=>{const home=f.team_h===p.team,opp=home?teamName(f.team_a):teamName(f.team_h);const d=fdrForFixture(f,p.team);return `<button class="fdr-chip fdr-${d}">${f.event?'GW'+f.event:'TBD'} · ${opp} (${home?'H':'A'}) · FDR ${d} · ${dec(projectFixture(p,f),1)} pts</button>`}).join('')}<button id="playerNews">News: ${esc(p.web_name)}</button></div><div class="all-stats">${fields.map(([k,v])=>`<div><span>${esc(k.replaceAll('_',' '))}</span><b>${typeof v==='number'?Number(v).toLocaleString(undefined,{maximumFractionDigits:3}):esc(v)}</b></div>`).join('')}</div>`;$('#closePlayer').onclick=()=>$('#playerDialog').close();$('#playerNews').onclick=()=>{$('#playerDialog').close();selectView('news');searchNews(p.web_name)};$('#playerDialog').showModal()}
function bindPlayerButtons(){$$('[data-details]').forEach(x=>{if(!x.closest('#playerTable'))x.onclick=e=>{e.stopPropagation();openPlayer(+x.dataset.details)}});$$('[data-compare]').forEach(x=>x.onclick=e=>{e.stopPropagation();toggleCompare(+x.dataset.compare)})}
async function renderLeagues(){const ls=state.entry?.leagues?.classic||[];if(!ls.length){$('#leagueCards').className='league-tabs empty';$('#leagueCards').textContent='No classic leagues found.';return}$('#leagueCards').className='league-tabs';$('#leagueCards').innerHTML=ls.map(l=>`<button class="league-tab ${state.leagueId===l.id?'active':''}" data-league="${l.id}"><b>${esc(l.name)}</b><span>Your rank ${l.entry_rank?`#${fmt(l.entry_rank)}`:'—'}</span></button>`).join('');$$('[data-league]').forEach(x=>x.onclick=()=>loadLeague(+x.dataset.league));if(!state.leagueId)loadLeague(ls[0].id)}
async function loadLeague(id){state.leagueId=id;$$('.league-tab').forEach(x=>x.classList.toggle('active',+x.dataset.league===id));$('#leagueLoadStatus').textContent='Loading…';$('#leagueStandings').innerHTML='<div class="loading-state"><i></i>Loading managers and squad ownership…</div>';$('#leagueExposure').innerHTML='<div class="loading-state"><i></i>Analyzing player exposure…</div>';try{const d=await api(`/api/fpl/league/${id}/analysis/${state.gw}?entry=${state.entryId}&limit=200`);state.leagueAnalysis=d;$('#leagueLoadStatus').textContent=`${d.managers.length} teams`;renderLeagueManagers();renderLeagueExposure();renderSquad()}catch(e){$('#leagueLoadStatus').textContent='Failed';$('#leagueStandings').innerHTML=`<div class="empty">${esc(e.message)}</div>`;$('#leagueExposure').innerHTML='<div class="empty">Could not calculate league exposure.</div>'}}
function renderLeagueManagers(){if(!state.leagueAnalysis)return;const q=($('#managerSearch').value||'').toLowerCase();const rows=state.leagueAnalysis.managers.filter(r=>!q||`${r.entry_name} ${r.player_name}`.toLowerCase().includes(q));$('#leagueStandingsTitle').textContent=state.leagueAnalysis.league?.name||'League standings';$('#leagueStandings').innerHTML=`<div class="manager-list">${rows.map(r=>`<div class="manager-row ${String(r.entry)===String(state.entryId)?'me':''}" data-manager="${r.entry}"><span class="manager-rank">${r.rank}</span><div><strong>${esc(r.entry_name)}</strong><small>${esc(r.player_name)}${String(r.entry)===String(state.entryId)?' · YOU':''}</small></div><div class="manager-points"><b>${fmt(r.event_total)}</b><span>GW</span></div><div class="manager-points"><b>${fmt(r.total)}</b><span>Total</span></div></div>`).join('')||'<div class="empty">No manager matches your search.</div>'}</div>`;$$('[data-manager]').forEach(x=>x.onclick=()=>openManagerTeam(+x.dataset.manager))}
function exposureClass(x){const own=ownIds().has(x.playerId);if(own&&x.selectionPct<=20)return'differential';if(own&&x.selectionPct>=65)return'shield';if(!own&&x.selectionPct>=35)return'risk';return'neutral'}
function renderLeagueExposure(){if(!state.leagueAnalysis)return;let rows=state.leagueAnalysis.exposure.map(x=>({...x,p:pById(x.playerId)})).filter(x=>x.p).map(x=>({...x,...enriched(x.p),type:exposureClass(x)}));if(state.leagueExposureFilter!=='all')rows=rows.filter(x=>x.type===state.leagueExposureFilter);rows.sort((a,b)=>{const av=a.type==='risk'?(a.selectionPct/100)*a.projected3:ownIds().has(a.playerId)?((100-a.selectionPct)/100)*a.projected3:0;const bv=b.type==='risk'?(b.selectionPct/100)*b.projected3:ownIds().has(b.playerId)?((100-b.selectionPct)/100)*b.projected3:0;return bv-av});$('#leagueExposure').innerHTML=`<div class="exposure-table">${rows.slice(0,60).map(x=>{const own=ownIds().has(x.playerId),impact=own?((100-x.selectionPct)/100)*x.projected3:-((x.selectionPct/100)*x.projected3);return `<div class="exposure-row" data-details="${x.playerId}">${img(photo(x.p),'',x.web_name)}<div><strong>${esc(x.web_name)}</strong><small>${x.teamName} · ${x.position} · ${own?'IN MY TEAM':'NOT OWNED'}</small></div><div class="exposure-metric"><b>${dec(x.selectionPct,1)}%</b><span>League selected</span></div><div class="exposure-metric"><b>${dec(x.captainPct,1)}%</b><span>Captain</span></div><div class="exposure-metric"><b>${impact>=0?'+':''}${dec(impact,1)}</b><span>3-GW impact</span></div><span class="tag ${x.type==='differential'?'diff':x.type}">${x.type.toUpperCase()}</span></div>`}).join('')}</div>`;$$('#leagueExposure [data-details]').forEach(x=>x.onclick=()=>openPlayer(+x.dataset.details))}
async function openManagerTeam(entry){const m=state.leagueAnalysis?.managers.find(x=>x.entry===entry);if(!m)return;$('#teamDialogContent').innerHTML='<div class="loading-state"><i></i>Loading team…</div>';$('#teamDialog').showModal();try{const d=await api(`/api/fpl/entry/${entry}/picks/${state.gw}`);const mine=ownIds(),theirs=new Set((d.picks||[]).map(x=>x.element)),common=[...theirs].filter(x=>mine.has(x)).length,uniqueMe=[...mine].filter(x=>!theirs.has(x)).length,uniqueThem=[...theirs].filter(x=>!mine.has(x)).length;$('#teamDialogContent').innerHTML=`<div class="team-dialog-head"><div><span class="eyebrow">LEAGUE TEAM</span><h2>${esc(m.entry_name)}</h2><p>${esc(m.player_name)} · Rank #${fmt(m.rank)} · ${fmt(m.total)} points</p></div><button class="icon-btn" id="closeTeam">×</button></div><div class="team-compare-summary"><div><span>Same players</span><b>${common}/15</b></div><div><span>Unique to me</span><b>${uniqueMe}</b></div><div><span>Unique to them</span><b>${uniqueThem}</b></div><div><span>GW points</span><b>${fmt(m.event_total)}</b></div></div><div class="team-squad-grid">${(d.picks||[]).map(pk=>{const p=pById(pk.element),mineHas=mine.has(pk.element);return p?`<div class="team-squad-player ${mineHas?'':'unique-them'}" data-details="${p.id}">${img(photo(p),'',p.web_name)}<b>${esc(p.web_name)}${pk.is_captain?' ©':''}</b><span>${teamName(p.team)} · ${POS[p.element_type]}</span><span>${mineHas?'Also in my team':'Unique to them'}</span></div>`:''}).join('')}</div>`;$('#closeTeam').onclick=()=>$('#teamDialog').close();$$('#teamDialog [data-details]').forEach(x=>x.onclick=()=>openPlayer(+x.dataset.details))}catch(e){$('#teamDialogContent').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function renderFixtures(){if(!state.teams.size||!state.fixtures.length)return;const h=state.fixtureHorizon||5,gws=nextFixtureGameweeks(h);if(!gws.length){$('#fixtureMatrix').className='fixture-matrix empty';$('#fixtureMatrix').textContent='No upcoming fixtures available.';return}let teams=[...state.teams.values()].map(t=>({...t,ease:teamFixtureEase(t.id,h)}));if(state.fixtureSort==='easiest')teams.sort((a,b)=>b.ease-a.ease);else if(state.fixtureSort==='hardest')teams.sort((a,b)=>a.ease-b.ease);else teams.sort((a,b)=>a.name.localeCompare(b.name));$('#fixtureMatrix').className='fixture-matrix';$('#fixtureMatrix').innerHTML=`<div class="fixture-row fixture-head" style="--fixture-cols:${gws.length}"><div>Club</div>${gws.map(g=>`<div>GW${g}</div>`).join('')}<div>Ease</div></div>${teams.map(t=>`<div class="fixture-row" style="--fixture-cols:${gws.length}"><div class="fixture-club">${img(crest(t.id),'',t.name)}<div><b>${esc(t.name)}</b><span>${esc(t.short_name)}</span></div></div>${gws.map(g=>{const fs=fixturesForTeamGw(t.id,g);if(!fs.length)return'<div><span class="matrix-fixture blank">—<small>Blank</small></span></div>';return `<div class="matrix-stack">${fs.map(f=>{const home=f.team_h===t.id,opp=home?teamName(f.team_a):teamName(f.team_h),d=fdrForFixture(f,t.id);return `<span class="matrix-fixture fdr-${d}"><b>${esc(opp)}</b><small>${home?'HOME':'AWAY'} · FDR ${d}</small></span>`}).join('')}</div>`}).join('')}<div class="fixture-ease"><b>${Math.round(t.ease)}</b><span>${t.ease>=75?'Favorable':t.ease>=55?'Balanced':'Difficult'}</span></div></div>`).join('')}`;if(state.picks){const own=(state.picks.picks||[]).map(pk=>({pk,p:pById(pk.element)})).filter(x=>x.p).map(x=>({...x,ease:fixtureScore(x.p,h),proj:projectedTotal(x.p,h)})).sort((a,b)=>b.ease-a.ease);$('#squadFixtureRun').className='squad-fixture-run';$('#squadFixtureRun').innerHTML=own.map(({pk,p,ease,proj})=>`<article class="squad-fixture-card" data-details="${p.id}">${img(photo(p),'',p.web_name)}<div class="squad-fixture-main"><div><b>${esc(p.web_name)}${pk.is_captain?' ©':''}</b><span>${teamName(p.team)} · ${POS[p.element_type]} · ease ${Math.round(ease)}/100</span></div>${fixtureMini(p,h,false)}</div><div class="squad-fixture-proj"><span>${h}-GW projection</span><b>${dec(proj,1)}</b><small>pts</small></div></article>`).join('');$$('#squadFixtureRun [data-details]').forEach(x=>x.onclick=()=>openPlayer(+x.dataset.details))}}
function renderSimulator(){if(!state.picks)return;const h=state.simHorizon,own=(state.picks.picks||[]).map(pk=>({pk,p:pById(pk.element)})).filter(x=>x.p),totals=own.map(x=>({p:x.p,total:projectedTotal(x.p,h)}));const xi=own.filter(x=>x.pk.position<=11),teamTotal=xi.reduce((s,x)=>s+projectedTotal(x.p,h)*Math.max(1,x.pk.multiplier||1),0),best=totals.sort((a,b)=>b.total-a.total)[0];$('#simulationSummary').innerHTML=`<div><span>Projected XI total</span><b>${dec(teamTotal,1)}</b></div><div><span>Horizon</span><b>${h} GWs</b></div><div><span>Best projected player</span><b>${esc(best?.p.web_name||'—')}</b></div><div><span>Model</span><b>FPL + fixtures</b></div>`;const maxG=Math.max(...upcomingFixtures(own[0]?.p||{team:-1},h).map(f=>f.event||state.gw+1),state.gw+h);const headers=Array.from({length:h},(_,i)=>state.gw+1+i);$('#simulationTable').className='sim-table';$('#simulationTable').innerHTML=`<div class="sim-grid head" style="--gwcols:${h}"><div>Player</div>${headers.map(g=>`<div>GW${g}</div>`).join('')}<div>Total</div></div>${own.map(({pk,p})=>{const fx=upcomingFixtures(p,h);const byGw=new Map(fx.map(f=>[f.event,f]));const total=fx.reduce((s,f)=>s+projectFixture(p,f),0);return `<div class="sim-grid" style="--gwcols:${h}"><div class="sim-player">${img(photo(p),'',p.web_name)}<div><b>${esc(p.web_name)}${pk.is_captain?' ©':''}</b><small>${teamName(p.team)} · ${POS[p.element_type]}</small></div></div>${headers.map(g=>{const f=byGw.get(g);if(!f)return'<div><span class="na">No fixture</span></div>';const home=f.team_h===p.team,opp=home?teamName(f.team_a):teamName(f.team_h),pts=projectFixture(p,f);const d=fdrForFixture(f,p.team);return `<div><b class="proj">${dec(pts,1)}</b><span class="fixture-chip ${home?'home':'away'} fdr-${d}">${opp} · ${home?'H':'A'} · <b>FDR ${d}</b><small>${fdrLabel(d)}</small></span></div>`}).join('')}<div><b class="proj">${dec(total,1)}</b></div></div>`}).join('')}`}
function renderNewsQuick(){if(!state.teams.size)return;$('#newsQuick').innerHTML=[...state.teams.values()].slice(0,20).map(t=>`<button data-news="${esc(t.name)}">${img(crest(t.id),'',t.name)} ${esc(t.short_name)}</button>`).join('');$$('[data-news]').forEach(x=>x.onclick=()=>searchNews(x.dataset.news))}
async function searchNews(q){q=(q||$('#newsSearch').value||'Premier League').trim();$('#newsSearch').value=q;$('#newsGrid').className='news-grid';$('#newsGrid').innerHTML='<div class="loading-state"><i></i>Searching latest headlines…</div>';try{const d=await api(`/api/news?q=${encodeURIComponent(q)}`);$('#newsGrid').innerHTML=(d.items||[]).map(n=>`<a class="news-card" href="${esc(n.link)}" target="_blank" rel="noopener"><small>${esc(n.source||'News')} · ${esc(n.when||'')}</small><h4>${esc(n.title)}</h4><p>${esc(n.description||'Open article')}</p></a>`).join('')||'<div class="empty">No headlines found.</div>'}catch(e){$('#newsGrid').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function loadHistory(){if(!state.entryId)return;try{const h=await api(`/api/history/${state.entryId}`);$('#historyTimeline').innerHTML=h.length?h.sort((a,b)=>new Date(b.ts)-new Date(a.ts)).map(s=>`<div class="timeline-item"><div class="gw">GW${s.gw}</div><div><b>${new Date(s.ts).toLocaleString()}</b><br><small>${esc(s.entry?.name||'')}</small></div><div><b>${fmt(s.entry?.summary_event_points)}</b><br><small>GW pts</small></div><div><b>#${fmt(s.entry?.summary_overall_rank)}</b><br><small>Rank</small></div><div><b>${money((s.entry?.last_deadline_value||0)/10)}</b><br><small>Value</small></div></div>`).join(''):'<div class="empty">No snapshots yet.</div>'}catch{}}

function track(event,meta={}){try{fetch('/api/activity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event,meta}),keepalive:true}).catch(()=>{})}catch{}}
async function loadAccount(){try{state.account=await api('/api/auth/me');}catch{state.account=null}renderAccount()}
function renderAccount(){const b=$('#accountBtn');if(!b)return;b.textContent=state.account?.user?.name||state.account?.user?.email||'Account';$('#accountLogout').style.display=state.account?.user?'block':'none'}
async function submitAccount(){const email=$('#accountEmail').value.trim(),password=$('#accountPassword').value,name=$('#accountName').value.trim();try{const endpoint=state.accountMode==='register'?'/api/auth/register':'/api/auth/login';state.account=await api(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,password,name})});$('#accountDialog').close();renderAccount();track('auth_'+state.accountMode);toast(state.accountMode==='register'?'Account created':'Signed in')}catch(e){toast(e.message)}}
function transferType(t){const pl=new Set([...state.teams.values()].flatMap(x=>[x.name,x.short_name]));const f=pl.has(t.from_club_name),to=pl.has(t.to_club_name);return f&&to?'internal':to?'in':f?'out':'other'}
function feeM(v){return Number.isFinite(Number(v))?Number(v)/1e6:null}
function renderTransfers(){if(!$('#transferTable'))return;let rows=[...state.transfers];const q=($('#transferSearch')?.value||'').toLowerCase(),from=$('#transferFrom')?.value||'',to=$('#transferTo')?.value||'',type=$('#transferType')?.value||'',season=$('#transferSeason')?.value||'2026',fee=optionalNumber('#transferFee'),op=$('#transferFeeOp')?.value||'>=';rows=rows.filter(t=>(!q||`${t.player_name} ${t.from_club_name} ${t.to_club_name}`.toLowerCase().includes(q))&&(!from||t.from_club_name===from)&&(!to||t.to_club_name===to)&&(!type||transferType(t)===type)&&(!season||String(t.transfer_season||'').startsWith(season))&&compareNum(feeM(t.transfer_fee),op,fee));rows=sortRows(rows,state.transferSort.key,state.transferSort.dir);$('#transferCount').textContent=`${rows.length} transfers`;$('#transferTable tbody').innerHTML=rows.map(t=>{const fm=feeM(t.transfer_fee),mv=feeM(t.market_value_in_eur),typ=transferType(t);return `<tr><td>${esc(t.transfer_date||'N/A')}</td><td><b>${esc(t.player_name)}</b></td><td>${esc(t.from_club_name||'N/A')}</td><td>→</td><td>${esc(t.to_club_name||'N/A')}</td><td>${fm==null?'<span class="na">N/A</span>':`€${fm.toFixed(fm>=10?1:2)}m`}</td><td>${mv==null?'<span class="na">N/A</span>':`€${mv.toFixed(mv>=10?1:2)}m`}</td><td>${esc(t.transfer_season||'')}</td><td><span class="data-pill ${typ==='in'?'full':typ==='out'?'partial':''}">${typ}</span></td></tr>`}).join('')||'<tr class="empty-row"><td colspan="9">No transfers match the selected filters.</td></tr>'}
async function loadMarketData(){try{const d=await api('/api/market-data');state.transfers=d.transfers||[];state.externalImages=new Map((d.images||[]).map(x=>[Number(x.fpl_id),x.image_url]));const clubs=[...new Set(state.transfers.flatMap(t=>[t.from_club_name,t.to_club_name]).filter(Boolean))].sort();for(const id of ['transferFrom','transferTo']){const s=$('#'+id);if(s)s.innerHTML='<option value="">All clubs</option>'+clubs.map(c=>`<option>${esc(c)}</option>`).join('')}renderTransfers();renderPlayers();renderTop();renderSquad()}catch(e){console.warn('Market data:',e.message)}}

function selectView(name){track('view',{name});$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===name));$$('.view').forEach(x=>x.classList.toggle('active',x.id===name));const n=$(`.nav[data-view="${name}"] b`);$('#pageTitle').textContent=n?.textContent||'Hisho FPL Hub';scrollTo({top:0,behavior:'smooth'})}

$$('.nav').forEach(x=>x.onclick=()=>selectView(x.dataset.view));$$('[data-go]').forEach(x=>x.onclick=()=>selectView(x.dataset.go));
$$('#topSegments button').forEach(x=>x.onclick=()=>{$$('#topSegments button').forEach(b=>b.classList.remove('active'));x.classList.add('active');state.topFilter=x.dataset.filter;renderTop()});
$$('#playerTable th[data-key]').forEach(th=>th.onclick=()=>{const k=th.dataset.key;if(state.sort.key===k)state.sort.dir=state.sort.dir==='asc'?'desc':'asc';else state.sort={key:k,dir:'desc'};renderPlayers()});
$$('#filterBar input,#filterBar select').forEach(x=>{x.oninput=renderPlayers;x.onchange=renderPlayers});$('#playerSearch').oninput=renderPlayers;$('#toggleFilters').onclick=()=>$('#filterBar').classList.toggle('collapsed');$('#resetSort').onclick=()=>{state.sort={key:'score',dir:'desc'};renderPlayers()};$('#clearFilters').onclick=()=>{$$('#filterBar input').forEach(x=>x.value='');$$('#filterBar select').forEach(x=>{if(x.id==='fRatingOp')x.value='>=';else if(x.id==='fPriceOp')x.value='<=';else if(x.id==='fDistOp')x.value='<=';else x.value=''});renderPlayers()};
$('#connectBtn').onclick=()=>$('#connectDialog').showModal();$('#connectSubmit').onclick=e=>{e.preventDefault();const id=$('#entryIdInput').value.trim();if(id){$('#connectDialog').close();connect(id)}};$('#refreshBtn').onclick=()=>state.entryId?connect(state.entryId):loadPublicData(true);
$('#freeTransfers').value=state.freeTransfers;$('#freeTransfers').onchange=()=>{state.freeTransfers=clamp(Number($('#freeTransfers').value)||1,1,5);localStorage.setItem('fplFreeTransfers',state.freeTransfers);$('#heroFT').textContent=state.freeTransfers;$('#mTransfers').textContent=state.freeTransfers;renderPlanner();renderDashboardActions()};$('#plannerHorizon').onchange=()=>{renderPlanner();renderDashboardActions()};$('#recalcPlanner').onclick=()=>{renderPlanner();toast('Transfer plan recalculated')};
$('#clearCompare').onclick=()=>{state.compare.clear();updateCompare();renderPlayers();renderTop();renderCompare()};$('#openCompare').onclick=()=>selectView('compare');
$('#managerSearch').oninput=renderLeagueManagers;$$('#leagueExposureFilter button').forEach(x=>x.onclick=()=>{$$('#leagueExposureFilter button').forEach(b=>b.classList.remove('active'));x.classList.add('active');state.leagueExposureFilter=x.dataset.exp;renderLeagueExposure()});
$$('#fixtureHorizon button').forEach(x=>x.onclick=()=>{$$('#fixtureHorizon button').forEach(b=>b.classList.remove('active'));x.classList.add('active');state.fixtureHorizon=+x.dataset.fh;renderFixtures()});$('#fixtureSort').onchange=()=>{state.fixtureSort=$('#fixtureSort').value;renderFixtures()};
$$('#simHorizon button').forEach(x=>x.onclick=()=>{$$('#simHorizon button').forEach(b=>b.classList.remove('active'));x.classList.add('active');state.simHorizon=+x.dataset.h;renderSimulator()});
$('#newsSearchBtn').onclick=()=>searchNews();$('#newsSearch').onkeydown=e=>{if(e.key==='Enter')searchNews()};
$('#snapshotBtn').onclick=async()=>{if(!state.entryId)return toast('Connect FPL first');try{await api(`/api/snapshot/${state.entryId}`,{method:'POST'});await loadHistory();toast(`GW${state.gw} snapshot saved`)}catch(e){toast(e.message)}};
$('#profileUpload').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{localStorage.setItem('hishoProfilePhoto',r.result);loadProfilePhoto();toast('Profile image updated')};r.readAsDataURL(f)};

$('#accountBtn').onclick=()=>{$('#accountDialog').showModal();renderAccount()};$('#accountModeToggle').onclick=()=>{state.accountMode=state.accountMode==='login'?'register':'login';$('#accountTitle').textContent=state.accountMode==='login'?'Sign in':'Create account';$('#accountSubmit').textContent=state.accountMode==='login'?'Sign in':'Create account';$('#accountModeToggle').textContent=state.accountMode==='login'?'Create new account':'I already have an account';$('#accountName').style.display=state.accountMode==='register'?'block':'none'};$('#accountSubmit').onclick=e=>{e.preventDefault();submitAccount()};$('#accountLogout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'});state.account=null;renderAccount();$('#accountDialog').close();toast('Signed out')}catch(e){toast(e.message)}};
for(const id of ['transferSearch','transferType','transferFrom','transferTo','transferSeason','transferFeeOp','transferFee']){const el=$('#'+id);if(el){el.oninput=renderTransfers;el.onchange=renderTransfers}}$$('#transferTable th[data-tkey]').forEach(th=>th.onclick=()=>{const k=th.dataset.tkey;if(state.transferSort.key===k)state.transferSort.dir=state.transferSort.dir==='asc'?'desc':'asc';else state.transferSort={key:k,dir:'desc'};renderTransfers()});$('#clearTransferFilters').onclick=()=>{$('#transferSearch').value='';$('#transferType').value='';$('#transferFrom').value='';$('#transferTo').value='';$('#transferFee').value='';renderTransfers()};

async function init(){loadProfilePhoto();updateCompare();setConnectState(false);await Promise.all([loadPublicData(),loadAccount()]);loadMarketData();if(state.entryId)await connect(state.entryId)}
init();


// iOS/PWA support
if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}))}
const isIOS=/iphone|ipad|ipod/i.test(navigator.userAgent);
const isStandalone=window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;
const installBtn=document.querySelector('#iosInstallHint');
if(installBtn){
  if(!isIOS||isStandalone) installBtn.style.display='none';
  else installBtn.onclick=()=>{toast('On iPhone/iPad: tap Share, then “Add to Home Screen”.')};
}
